def save_datasets():
    os.makedirs("apps/nlp/evaluation/data", exist_ok=True)
    
    with open("apps/nlp/evaluation/data/classification_eval_set.json", "w") as f:
        json.dump(CLASSIFICATION_DATA, f, indent=2)
    print(f"✅ Saved classification dataset: {len(CLASSIFICATION_DATA)} samples")

    with open("apps/nlp/evaluation/data/duplicate_eval_set.json", "w") as f:
        json.dump(DUPLICATE_DATA, f, indent=2)
    print(f"✅ Saved duplicate evaluation dataset: {len(DUPLICATE_DATA)} pairs")

if __name__ == "__main__":
    save_datasets()
